    roads = [[1] * (n+1) for _ in range(n+1)]

    for u, v in railways:
        graph[u].append(v)
        graph[v].append(u)
        roads[u][v] = roads[v][u] = 0

    def bfs(start, is_train):
        queue = deque([(start, 0)])
        visited = [False] * (n+1)
        visited[start] = True

        while queue:
            node, time = queue.popleft()

            if node == n:
                return time

            for neighbor in range(1, n+1):
