                    visited[neighbor] = True
                    queue.append((neighbor, time + 1))

        return float('inf')

    train_time = bfs(1, True)
    bus_time = bfs(1, False)

    if train_time == float('inf') or bus_time == float('inf'):
        return -1

    return max(train_time, bus_time)

