from collections import deque, defaultdict

def min_arrival_time(n, m, railways):
    # Build the adjacency list for railways (train paths)
    train_graph = defaultdict(list)
    for u, v in railways:
        train_graph[u].append(v)
        train_graph[v].append(u)

    # Build the adjacency list for roads (bus paths)
    road_graph = defaultdict(list)
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if i not in train_graph or j not in train_graph[i]:
                road_graph[i].append(j)
                road_graph[j].append(i)

    # BFS for shortest path in train graph
    def bfs_train(src, dest):
        queue = deque([(src, 0)])
        visited = set([src])
        while queue:
            node, dist = queue.popleft()
            if node == dest:
                return dist
            for neighbor in train_graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, dist + 1))
        return float('inf')

    # BFS for shortest path in road graph
    def bfs_road(src, dest):
        queue = deque([(src, 0)])
        visited = set([src])
        while queue:
            node, dist = queue.popleft()
            if node == dest:
                return dist
            for neighbor in road_graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, dist + 1))
        return float('inf')

    # Calculate shortest paths
    train_time = bfs_train(1, n)
    road_time = bfs_road(1, n)

    # Determine if it's possible to reach town n
    if train_time == float('inf') and road_time == float('inf'):
        return -1

    # Find the minimum time for the later vehicle's arrival
    return max(train_time, road_time)

